package com.ecole.gestion_scolaire.accountactivation.service;
import com.ecole.gestion_scolaire.accountactivation.dto.ActivationDtos.*; import com.ecole.gestion_scolaire.accountactivation.entity.AccountActivationToken; import com.ecole.gestion_scolaire.accountactivation.repository.AccountActivationTokenRepository;
import com.ecole.gestion_scolaire.identity.entity.*; import com.ecole.gestion_scolaire.identity.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.ApplicationContext; import org.springframework.core.io.ClassPathResource; import org.springframework.core.io.Resource; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import jakarta.persistence.EntityManager; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.OffsetDateTime; import java.util.*;
@Service public class AccountActivationService {
 private final PersonRepository persons; private final UserAccountRepository users; private final RoleRepository roles; private final UserRoleRepository userRoles; private final AccountActivationTokenRepository tokens; private final PasswordEncoder encoder; private final ApplicationContext context; private final EntityManager em;
 @Value("${app.frontend-url:http://localhost:4200}") private String frontendUrl; @Value("${app.finance-email.from:sls.school2008@gmail.com}") private String from; @Value("${app.finance-email.from-name:Groupe Scolaire Sciences et Lettres}") private String fromName;
 public AccountActivationService(PersonRepository p,UserAccountRepository u,RoleRepository r,UserRoleRepository ur,AccountActivationTokenRepository t,PasswordEncoder e,ApplicationContext c,EntityManager em){persons=p;users=u;roles=r;userRoles=ur;tokens=t;encoder=e;context=c;this.em=em;}
 @Transactional public ActivateResponse activate(ActivateRequest req){ if(req==null||req.personId()==null||blank(req.roleCode()))throw new IllegalArgumentException("Personne et rôle sont obligatoires.");
  var person=persons.findById(req.personId()).orElseThrow(()->new IllegalArgumentException("Personne introuvable.")); if(blank(person.getEmail()))throw new IllegalArgumentException("Une adresse e-mail est obligatoire avant l'activation du compte.");
  String username=resolveMatricule(person.getId(),req.matricule(),req.roleCode()); var existing=users.findByPersonId(person.getId()); UserAccount user;
  if(existing.isPresent()){user=existing.get(); if(user.getStatus()==UserAccountStatus.ACTIVE)throw new IllegalArgumentException("Ce compte est déjà actif."); if(!user.getUsername().equalsIgnoreCase(username)&&users.existsByUsername(username))throw new IllegalArgumentException("Ce matricule est déjà utilisé."); user.setUsername(username);}
  else {if(users.existsByUsername(username))throw new IllegalArgumentException("Ce matricule est déjà utilisé."); user=new UserAccount(); user.setPerson(person); user.setUsername(username); user.setPasswordHash(encoder.encode(UUID.randomUUID().toString()));}
  user.setStatus(UserAccountStatus.PENDING); user.setMustChangePassword(true); user.setFailedLoginAttempts(0); user.setLockedUntil(null); user=users.save(user);
  var role=roles.findByCode(req.roleCode().trim().toUpperCase(Locale.ROOT)).orElseThrow(()->new IllegalArgumentException("Rôle introuvable."));
  if(!userRoles.existsByUserAccountIdAndRoleId(user.getId(),role.getId())){var ur=new UserRole(); ur.setId(new UserRoleId(user.getId(),role.getId())); ur.setUserAccount(user); ur.setRole(role); userRoles.save(ur);}
  String raw=randomToken(); var token=new AccountActivationToken(); token.setUserAccount(user); token.setTokenHash(hash(raw)); token.setExpiresAt(OffsetDateTime.now().plusHours(24)); tokens.save(token);
  boolean sent=send(person.getEmail(),person.getFirstName(),username,raw); return new ActivateResponse(user.getId(),username,person.getEmail(),user.getStatus().name(),sent); }
 @Transactional(readOnly=true) public TokenStatus status(String raw){var t=findValid(raw); var p=t.getUserAccount().getPerson(); return new TokenStatus(true,t.getUserAccount().getUsername(),p.getFirstName(),p.getLastName());}
 @Transactional public void setPassword(SetPasswordRequest r){if(r==null||blank(r.password())||!Objects.equals(r.password(),r.confirmPassword()))throw new IllegalArgumentException("Le mot de passe et sa confirmation doivent correspondre."); if(r.password().length()<8)throw new IllegalArgumentException("Le mot de passe doit contenir au moins 8 caractères."); var t=findValid(r.token()); var u=t.getUserAccount(); u.setPasswordHash(encoder.encode(r.password()));u.setStatus(UserAccountStatus.ACTIVE);u.setMustChangePassword(false);u.setPasswordChangedAt(OffsetDateTime.now());users.save(u);t.setUsedAt(OffsetDateTime.now());tokens.save(t);}
 private AccountActivationToken findValid(String raw){if(blank(raw))throw new IllegalArgumentException("Lien d'activation invalide.");var t=tokens.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Lien d'activation invalide."));if(t.getUsedAt()!=null||t.getExpiresAt().isBefore(OffsetDateTime.now()))throw new IllegalArgumentException("Ce lien d'activation a expiré ou a déjà été utilisé.");return t;}
 private boolean send(String email,String firstName,String matricule,String raw){try{Class<?> sc=Class.forName("org.springframework.mail.javamail.JavaMailSender");Object sender=context.getBean(sc);Object msg=sc.getMethod("createMimeMessage").invoke(sender);Class<?> mc=Class.forName("jakarta.mail.internet.MimeMessage");Class<?> hc=Class.forName("org.springframework.mail.javamail.MimeMessageHelper");Object h=hc.getConstructor(mc,boolean.class,String.class).newInstance(msg,true,"UTF-8");hc.getMethod("setTo",String.class).invoke(h,email);hc.getMethod("setSubject",String.class).invoke(h,"Activation de votre compte scolaire");String link=frontendUrl.replaceAll("/$","")+"/activation?token="+raw;String html="<p>Bonjour "+esc(firstName)+",</p><p>Votre compte a été préparé.</p><p><b>Identifiant de connexion (matricule) : "+esc(matricule)+"</b></p><p><a href=\""+link+"\">Définir mon mot de passe</a></p><p>Ce lien est valable 24 heures et utilisable une seule fois.</p>";hc.getMethod("setText",String.class,boolean.class).invoke(h,html,true);hc.getMethod("setFrom",String.class,String.class).invoke(h,from,fromName);Resource logo=new ClassPathResource("sls-logo.png");if(logo.exists())hc.getMethod("addInline",String.class,Resource.class).invoke(h,"slsLogo",logo);sc.getMethod("send",mc).invoke(sender,msg);return true;}catch(Exception e){return false;}}
 private String resolveMatricule(Long personId,String supplied,String roleCode){if(!blank(supplied))return supplied.trim().toUpperCase(Locale.ROOT);String role=roleCode.trim().toUpperCase(Locale.ROOT);List<?> r;if("ELEVE".equals(role)){r=em.createNativeQuery("select student_number from student where person_id=:p limit 1").setParameter("p",personId).getResultList();}else if("ENSEIGNANT".equals(role)||!"PARENT".equals(role)){r=em.createNativeQuery("select employee_number from employee where person_id=:p limit 1").setParameter("p",personId).getResultList();}else{r=em.createNativeQuery("select concat('PAR',lpad(id::text,6,'0')) from guardian where person_id=:p limit 1").setParameter("p",personId).getResultList();}if(r.isEmpty()||r.get(0)==null)throw new IllegalArgumentException("Aucun matricule ne peut être déterminé pour cette personne.");return r.get(0).toString().trim().toUpperCase(Locale.ROOT);}
 private static String randomToken(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} private static String hash(String s){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(d);}catch(Exception e){throw new IllegalStateException(e);}} private static boolean blank(String s){return s==null||s.isBlank();} private static String esc(String s){return s==null?"":s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
}
